 29	/**
 30	 * Configuration accepted by `startServer()`.
 31	 *
 32	 * Most fields are pulled directly from `AppConfig`; `serverPort` and
 33	 * `pollIntervalSeconds` can be overridden here so callers (especially tests)
 34	 * can spin up an ephemeral server on port 0 without editing the full config.
 35	 */
 36	export interface ServerConfig {
 37	    /** TCP port to listen on.  Defaults to `config.serverPort ?? 4200`. */
 38	    serverPort?: number;
 39	    /** Absolute path to the directory of static files to serve. */
 40	    staticDir: string;
 41	    /** How often (in seconds) to poll git remotes.  Defaults to 30. */
 42	    pollIntervalSeconds?: number;
 43	    /** Full application config forwarded to managers / orchestrators. */
 44	    appConfig: AppConfig;
 45	}
