232	        if (typeof host !== 'string' || host.trim() === '') {
233	            sendError(res, 400, 'Missing or invalid field "host": must be a non-empty string.');
234	            return;
235	        }
236	        if (typeof token !== 'string' || token.trim() === '') {
237	            sendError(res, 400, 'Missing or invalid field "token": must be a non-empty string.');
238	            return;
239	        }
240	
241	        // Validate optional `id` field when provided.
242	        if (id !== undefined && (typeof id !== 'string' || id.trim() === '')) {
243	            sendError(res, 400, 'Field "id", when provided, must be a non-empty string.');
244	            return;
245	        }
246	
247	        const cleanLabel = label.trim();
248	        const cleanHost = host.trim();
249	        const cleanToken = token.trim();
250	
251	        const existingCredentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
252	
253	        let savedEntry: GitCredentialEntry;
254	        let auditOperation: string;
255	
256	        if (id !== undefined) {
257	            // --- Upsert path: id is explicitly provided ---
258	            const cleanId = (id as string).trim();
259	            const existingIndex = existingCredentials.findIndex((e) => e.id === cleanId);
260	
261	            if (existingIndex === -1) {
262	                // New entry with an explicit ID — no existing entry matches, so create.
263	                savedEntry = { id: cleanId, label: cleanLabel, host: cleanHost, token: cleanToken };
264	                appConfig.gitCredentials = [...existingCredentials, savedEntry];
265	                auditOperation = 'create-credential';
266	            } else {
267	                // Replace the existing entry at the same position.
268	                savedEntry = { id: cleanId, label: cleanLabel, host: cleanHost, token: cleanToken };
269	                const updated = [...existingCredentials];
270	                updated[existingIndex] = savedEntry;
271	                appConfig.gitCredentials = updated;
272	                auditOperation = 'update-credential';
273	            }
274	        } else {
275	            // --- Create path: no id provided — auto-generate from label ---
276	            const existingIds = new Set(existingCredentials.map((e) => e.id));
277	            const newId = generateUniqueId(cleanLabel, existingIds);
278	            savedEntry = { id: newId, label: cleanLabel, host: cleanHost, token: cleanToken };
279	            appConfig.gitCredentials = [...existingCredentials, savedEntry];
280	            auditOperation = 'create-credential';
281	        }
282	
283	        // Persist to disk.
284	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
285	
286	        // Audit log — never include the token value.
287	        errorLogManager?.append({
288	            Severity: 'warning',
289	            Source: 'credential-audit',
290	            Operation: auditOperation,
291	            Context: {},
292	            Message: `Credential "${savedEntry.id}" (label: "${savedEntry.label}", host: "${savedEntry.host}") was ${auditOperation === 'create-credential' ? 'created' : 'updated'}.`,
293	        });
294	
295	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
296	    });
